<template>
  <q-item
    clickable
    v-ripple
    v-if="!showLanguageDropdown"
    data-test="language-selector"
    aria-label="Change language"
    aria-haspopup="menu"
  >
    <q-item-section avatar>
      <q-icon class="icon-grey" name="language" />
    </q-item-section>
    <q-item-section class="text-capitalize">
      {{currentLanguage}}
    </q-item-section>
    <q-item-section side>
      <q-icon name="keyboard_arrow_right" />
    </q-item-section>
    <q-menu
      anchor="top end"
      self="top start"
      :offset="[1, 0]"
      style="border-radius: 4px; min-width: 560px"
      class="no-shadow gray-border"
      data-test="language-menu"
    >
      <div class="language-grid">
        <template v-for="(language, index) in languages_list" :key="index">
          <q-item
            clickable
            @click="changeLang(language.value)"
            v-ripple
            :active="language.value == locale"
            :data-test="`language-option-${language.value}`"
            :aria-label="`Select ${language.label}`"
            role="menuitem"
            class="language-item"
          >
            <q-item-section
              avatar
              class="no-padding"
              style="min-width: 28px !important"
            >
              <img
                :src="getFlagImageUrl(language.flag)"
                :alt="`${language.label} flag`"
                width="24"
                height="18"
              />
            </q-item-section>
            <q-item-section class="text-capitalize language-label">{{
              language.label
            }}</q-item-section>
            <q-item-section
              v-if="language.value == locale"
              avatar
              class="no-padding check-icon"
              style="min-width: 20px !important"
            >
              <q-icon name="check" color="primary" size="16px" />
            </q-item-section>
          </q-item>
        </template>
      </div>
    </q-menu>
  </q-item>

  <q-select
    v-else
    v-model="locale"
    :options="languages_list"
    dense
    borderless
    emit-value
    map-options
    options-dense
    popup-content-class="text-capitalize"
    @update:model-value="
      (val: any) => {
        changeLang(val);
      }
    "
    class="float-right q-ml-auto text-grey-7 text-uppercase q-mr-md"
    data-test="language-dropdown"
    aria-label="Select language"
  />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { useTolgee, useTranslate } from '@tolgee/vue';
import { defineComponent, computed, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { LocalStorage, SessionStorage } from 'quasar';
import { toRegionalLanguageCode } from 'src/boot/tolgee';
import { useDropdownStore, useSettingStore } from 'src/store/main';
import { preferred_language_setting, CONSTANTS } from 'src/constants';

export default defineComponent({
  name: 'LanguageDropdown',
  props: {
    showLanguageDropdown: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    currentLanguage(): string {
      const language = this.languages_list.find((lang: any) => lang.value === this.locale);
      return language ? this.$t(language.label) : '';
    }
  },
  async mounted() {
    this.getLanguageList();
    await this.initLocaleFromSettings();
  },
  methods: {
    async initLocaleFromSettings() {
      const savedLanguage = await this.getUserBasedSettings(preferred_language_setting);
      if (savedLanguage && savedLanguage !== 'undefined' && savedLanguage !== 'null') {
        this.locale = savedLanguage;
      }
    },

    reloadWithLanguageChange() {
      SessionStorage.set('event_name', 'language_change');
      LocalStorage.remove('doc_types');
      window.location.reload();
    },
    async changeLang(language: any) {
      // Update locale immediately for UI feedback
      this.locale = language;

      // Split language code (e.g., 'en-us' -> 'en')
      const lang_split = language.split('-')[0];

      // Change Tolgee language (this updates translations reactively)
      await this.tolgee.changeLanguage(lang_split);

      // Now handle backend save and cache clearing
      await this.languageChanged(language);
    },

    async languageChanged(option: dynamicObj) {
      try {
        // Save to LocalStorage (immediate UI feedback)
        LocalStorage.set(CONSTANTS.selected_language, option);

        // Save to backend user preferences
        const settings_store = useSettingStore();
        await settings_store.setUserPreferences(
          preferred_language_setting,
          option,
        );
      } catch (err) {
        (window as any).logError?.(err);
      } finally {
        // Always reload to apply language changes (even if backend save fails)
        this.reloadWithLanguageChange();
      }
    },
  },
  setup() {
    const { t } = useTranslate();
    const tolgee = useTolgee(['language', 'pendingLanguage']);

    // Create a reactive locale ref that syncs with Tolgee. Tolgee reports a
    // normalised base code ('en'); map it to the regional code ('en-us') the
    // dropdown options are keyed on so the active option highlights correctly.
    const locale = computed({
      get: () => toRegionalLanguageCode(tolgee.value.getLanguage()),
      set: (val: string) => tolgee.value.changeLanguage(val),
    });

    const dropdown_store = useDropdownStore();
    const { languagesListReactive: languages_list } = storeToRefs(dropdown_store);
    const { getLanguageList, getFlagImageUrl } = dropdown_store;

    const settings_store = useSettingStore();
    const { getUserBasedSettings } = settings_store;

    return {
      tolgee,
      languages_list,
      getLanguageList,
      getFlagImageUrl,
      getUserBasedSettings,
      locale,
    };
  },
});
</script>

